CREATE OR REPLACE FUNCTION public.content_resolution_append_only()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND TG_TABLE_NAME = 'question_content_revisions' THEN
    IF NEW.id IS NOT DISTINCT FROM OLD.id
       AND NEW.question_id IS NOT DISTINCT FROM OLD.question_id
       AND NEW.before_content IS NOT DISTINCT FROM OLD.before_content
       AND NEW.after_content IS NOT DISTINCT FROM OLD.after_content
       AND NEW.before_sha256 IS NOT DISTINCT FROM OLD.before_sha256
       AND NEW.after_sha256 IS NOT DISTINCT FROM OLD.after_sha256 THEN
      RETURN NEW;
    END IF;
  END IF;
  RAISE EXCEPTION '% is append-only', TG_TABLE_NAME;
END;
$$;
DO $do$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname = 'question_marking_specs' AND t.tgname = 'question_marking_specs_append_only' AND NOT t.tgisinternal) THEN
    EXECUTE $guard$CREATE TRIGGER question_marking_specs_append_only
  BEFORE UPDATE OR DELETE ON public.question_marking_specs
  FOR EACH ROW EXECUTE FUNCTION public.content_resolution_append_only()$guard$;
  END IF;
END
$do$;
DO $do$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname = 'question_content_revisions' AND t.tgname = 'question_content_revisions_append_only' AND NOT t.tgisinternal) THEN
    EXECUTE $guard$CREATE TRIGGER question_content_revisions_append_only
  BEFORE UPDATE OR DELETE ON public.question_content_revisions
  FOR EACH ROW EXECUTE FUNCTION public.content_resolution_append_only()$guard$;
  END IF;
END
$do$;
DO $do$
BEGIN
