-- ===== from 20260919175907_a6cec947-baea-4506-9661-db7cef48a32a.sql =====
INSERT INTO public.question_pool_exclusions (org_id, question_id, external_ref, pool, reason, work_item_ref, active)
SELECT q.org_id, q.id, q.external_ref, 'paid',
  'Engine v1.0.0 quarantined; no named-SME approval. Not eligible for paid selection.',
  NULL, true
FROM public.question_bank q
JOIN public.question_auto_verifications av ON av.question_id = q.id AND av.outcome = 'quarantined'
ON CONFLICT (question_id, pool) DO NOTHING;
INSERT INTO public.remediation_work_items (org_id, ref, title, severity, status, details)
SELECT q.org_id, 'REASSESSMENT-146ec7c8-POOL-BREACH', 'Published reassessment 146ec7c8 served diagnostic-pool items (REQ001-DIAG-001/005/009)', 'P0', 'open',
  jsonb_build_object(
    'reassessment_id','146ec7c8',
    'requirements', jsonb_build_array('REQ001-DIAG-001','REQ001-DIAG-005','REQ001-DIAG-009'),
    'external_refs', jsonb_build_array('C10-2627-MATH-REQ001-DIAG-001','C10-2627-MATH-REQ001-DIAG-005','C10-2627-MATH-REQ001-DIAG-009'),
    'condition','C1',
    'action_taken','excluded from paid diagnostic capacity in production',
    'not_done', jsonb_build_array('no deletion','no silent pool reclassification'),
    'resolution_required_before','paid diagnostic reuse')
FROM public.question_bank q
WHERE q.external_ref = 'C10-2627-MATH-REQ001-DIAG-001'
ON CONFLICT (ref) DO NOTHING;
INSERT INTO public.question_pool_exclusions (org_id, question_id, external_ref, pool, reason, work_item_ref, active)
SELECT q.org_id, q.id, q.external_ref, 'paid_diagnostic',
  'C1: served inside published reassessment 146ec7c8; excluded from paid diagnostic capacity until the pool breach is resolved.',
  'REASSESSMENT-146ec7c8-POOL-BREACH', true
FROM public.question_bank q
WHERE q.external_ref IN ('C10-2627-MATH-REQ001-DIAG-001','C10-2627-MATH-REQ001-DIAG-005','C10-2627-MATH-REQ001-DIAG-009')
ON CONFLICT (question_id, pool) DO NOTHING;

-- ===== from 20260919195620_b30e9647-5517-4603-9c1c-6d244ee2c4b3.sql =====
CREATE TABLE IF NOT EXISTS public.question_commercial_release (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL REFERENCES public.organizations(id),
  question_id uuid NOT NULL REFERENCES public.question_bank(id) ON DELETE CASCADE,
  external_ref text,
  subject text NOT NULL,
  release_basis text NOT NULL DEFAULT 'FOUNDER_APPROVED_AUTOMATED_PRODUCTION',
  commercial_classification text NOT NULL,
  classification_basis text NOT NULL,
  content_sha256 text NOT NULL,
  engine_version text NOT NULL,
  activation_run_id uuid NOT NULL,
  paid_selection_eligible boolean NOT NULL DEFAULT false,
  production_export_eligible boolean NOT NULL DEFAULT false,
  human_sme_certified boolean NOT NULL DEFAULT false,
  official_cbse_ncert_certified boolean NOT NULL DEFAULT false,
  copyright_permission_claimed boolean NOT NULL DEFAULT false,
  automated_not_human boolean NOT NULL DEFAULT true,
  evidence jsonb NOT NULL DEFAULT '{}'::jsonb,
  activated_at timestamptz NOT NULL DEFAULT now(),
  revoked_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT qcr_basis_chk CHECK (release_basis = 'FOUNDER_APPROVED_AUTOMATED_PRODUCTION'),
  CONSTRAINT qcr_class_chk CHECK (commercial_classification = ANY (ARRAY[
    'ORIGINAL_EDUOS_CONTENT','FACT_OR_FORMULA_ONLY','EXPLICITLY_OPEN_LICENSED',
    'PERMISSION_DOCUMENTED','COMMERCIAL_USE_BLOCKED'])),
  CONSTRAINT qcr_no_human_cert_chk CHECK (human_sme_certified = false),
  CONSTRAINT qcr_no_official_cert_chk CHECK (official_cbse_ncert_certified = false),
  CONSTRAINT qcr_no_copyright_claim_chk CHECK (copyright_permission_claimed = false),
  CONSTRAINT qcr_not_human_chk CHECK (automated_not_human = true),
  CONSTRAINT qcr_blocked_not_eligible_chk CHECK (
    commercial_classification <> 'COMMERCIAL_USE_BLOCKED'
    OR (paid_selection_eligible = false AND production_export_eligible = false)),
  CONSTRAINT qcr_question_run_key UNIQUE (question_id, activation_run_id)
);
DO $do$
BEGIN
  IF to_regclass('public.question_commercial_release') IS NOT NULL THEN
    EXECUTE $guard$GRANT SELECT ON public.question_commercial_release TO authenticated$guard$;
  END IF;
END
$do$;
DO $do$
BEGIN
  IF to_regclass('public.question_commercial_release') IS NOT NULL THEN
    EXECUTE $guard$GRANT ALL ON public.question_commercial_release TO service_role$guard$;
  END IF;
END
$do$;
DO $do$
BEGIN
  IF to_regclass('public.question_commercial_release') IS NOT NULL THEN
    EXECUTE $guard$ALTER TABLE public.question_commercial_release ENABLE ROW LEVEL SECURITY$guard$;
  END IF;
END
$do$;
DO $do$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'question_commercial_release' AND policyname = 'qcr_select_staff') THEN
    EXECUTE $guard$CREATE POLICY "qcr_select_staff" ON public.question_commercial_release
  FOR SELECT TO authenticated
  USING (org_id = private.current_org_id() AND (private.is_staff() OR private.is_reviewer()))$guard$;
  END IF;
END
$do$;
DO $do$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname = 'question_commercial_release' AND t.tgname = 'touch_question_commercial_release' AND NOT t.tgisinternal) THEN
    EXECUTE $guard$CREATE TRIGGER touch_question_commercial_release
  BEFORE UPDATE ON public.question_commercial_release
  FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at()$guard$;
  END IF;
END
$do$;
CREATE INDEX IF NOT EXISTS idx_qcr_question ON public.question_commercial_release (question_id);
CREATE INDEX IF NOT EXISTS idx_qcr_active ON public.question_commercial_release (org_id) WHERE revoked_at IS NULL;
CREATE OR REPLACE VIEW public.production_release_pool AS
  SELECT r.org_id,
         r.question_id,
         r.external_ref,
         r.subject,
         r.release_basis,
         r.commercial_classification,
         r.content_sha256,
         r.paid_selection_eligible,
         r.production_export_eligible
  FROM public.question_commercial_release r
  WHERE r.revoked_at IS NULL
    AND r.paid_selection_eligible = true
    AND NOT EXISTS (
      SELECT 1 FROM public.question_pool_exclusions e
      WHERE e.question_id = r.question_id AND e.active = true
    );
DO $do$
BEGIN
  IF to_regclass('public.production_release_pool') IS NOT NULL THEN
    EXECUTE $guard$GRANT SELECT ON public.production_release_pool TO authenticated$guard$;
  END IF;
END
$do$;
DO $do$
BEGIN
  IF to_regclass('public.production_release_pool') IS NOT NULL THEN
    EXECUTE $guard$GRANT SELECT ON public.production_release_pool TO service_role$guard$;
  END IF;
END
$do$;

