-- ===== from 20261002050331_7ac11e74-e65e-4d5e-9ab7-443ab74e82ce.sql =====
CREATE OR REPLACE FUNCTION private.is_platform_owner()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM auth.users u
    WHERE u.id = auth.uid()
      AND lower(trim(u.email)) = 'rmanish2000@gmail.com'
      AND u.email_confirmed_at IS NOT NULL
  );
$$;
REVOKE EXECUTE ON FUNCTION private.is_platform_owner() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION private.is_platform_owner() TO authenticated, service_role;

-- ===== PR #5 hardened owner policies on pilot_leads (ensure present) =====
DO $do$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'pilot_leads' AND policyname = 'Platform owner reads pilot applications') THEN
    EXECUTE $guard$CREATE POLICY "Platform owner reads pilot applications" ON public.pilot_leads FOR SELECT TO authenticated USING (private.is_platform_owner())$guard$;
  END IF;
END
$do$;
DO $do$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'pilot_leads' AND policyname = 'Platform owner updates pilot applications') THEN
    EXECUTE $guard$CREATE POLICY "Platform owner updates pilot applications" ON public.pilot_leads FOR UPDATE TO authenticated USING (private.is_platform_owner()) WITH CHECK (private.is_platform_owner())$guard$;
  END IF;
END
$do$;
